// Explicit Unity, VFX, progression, status and enemy side-effect boundaries.
using System;using System.Collections.Generic;
namespace UnityEngine
{
 public class MonoBehaviour{public GameObject gameObject=new GameObject();public Transform transform=>gameObject.transform;public static void Destroy(GameObject obj){obj.activeInHierarchy=false;}}
 public class GameObject{public bool activeInHierarchy=true;public Transform transform=new Transform();public GameObject(string name=""){}public T AddComponent<T>()where T:MonoBehaviour,new(){var v=new T();v.gameObject=this;return v;}}
 public class Transform{public Vector3 position,forward=Vector3.forward;}
 public struct Vector3{public float x,y,z;public Vector3(float x,float y,float z){this.x=x;this.y=y;this.z=z;}public static Vector3 zero=>new Vector3();public static Vector3 up=>new Vector3(0,1,0);public static Vector3 down=>new Vector3(0,-1,0);public static Vector3 forward=>new Vector3(0,0,1);public float sqrMagnitude=>x*x+y*y+z*z;public float magnitude=>(float)Math.Sqrt(sqrMagnitude);public Vector3 normalized=>magnitude>.000001f?this/magnitude:zero;public static Vector3 operator+(Vector3 a,Vector3 b)=>new Vector3(a.x+b.x,a.y+b.y,a.z+b.z);public static Vector3 operator-(Vector3 a,Vector3 b)=>new Vector3(a.x-b.x,a.y-b.y,a.z-b.z);public static Vector3 operator-(Vector3 a)=>zero-a;public static Vector3 operator*(Vector3 a,float b)=>new Vector3(a.x*b,a.y*b,a.z*b);public static Vector3 operator/(Vector3 a,float b)=>a*(1/b);public static float Angle(Vector3 a,Vector3 b)=>a.sqrMagnitude*b.sqrMagnitude<.000001f?0:(float)(Math.Acos(Math.Max(-1,Math.Min(1,(a.x*b.x+a.y*b.y+a.z*b.z)/(a.magnitude*b.magnitude))))*180/Math.PI);}
 public struct Color{public float r,g,b,a;public Color(float r,float g,float b,float a=1){this.r=r;this.g=g;this.b=b;this.a=a;}}
 public static class Mathf{public static float Min(float a,float b)=>Math.Min(a,b);public static float Clamp(float v,float a,float b)=>Math.Max(a,Math.Min(b,v));public static float Clamp01(float v)=>Clamp(v,0,1);public static float Pow(float a,float b)=>(float)Math.Pow(a,b);public static float Sin(float v)=>(float)Math.Sin(v);}
 public static class Time{public static float deltaTime=.1f;}
}
