 public enum HeroClass{Vanguard,Arcanist,Ranger,Summoner}public enum ElementalistSpecialization{Balanced,Burn,Shatter}public enum SummonerRoute{Pack}public enum EquipmentMechanic{CinderTrail,VenomSpread}public enum CombatVisualPriority{ActionBody,RealContact}public enum FilledVfxKind{Summon}public enum SkillPerformanceBody{Gravity,Spirit}public enum SkillVisualRecipe{Poison}
 public struct CombatDamage{public float Amount;public bool IsCritical;public float CriticalMultiplier;public CombatDamage(float value){Amount=value;IsCritical=false;CriticalMultiplier=1.65f;}public CombatDamage WithoutCritical()=>new CombatDamage(Amount);public static implicit operator CombatDamage(float v)=>new CombatDamage(v);public static CombatDamage operator*(CombatDamage a,float b)=>new CombatDamage(a.Amount*b);}
 public static class Trace{public static readonly List<int> Damage=new List<int>(16384),Interrupt=new List<int>(16384),Poison=new List<int>(16384);public static void Clear(){Damage.Clear();Interrupt.Clear();Poison.Clear();}}
 public class EnemyController:MonoBehaviour{public int Id;public float Health=1000000,HitFootprintBonus;public bool IsDead,IsBoss,Blocked;public EnemyStatusEffects StatusEffects;public Action Hit;public int Pulls,ProvokeCount;public Vector3 LastPull;public EnemyController(int id=0,float x=0,float z=1){Id=id;transform.position=new Vector3(x,0,z);StatusEffects=new EnemyStatusEffects(this);}public void TrySkillInterrupt(PlayerController p,int skill,int cast){Trace.Interrupt.Add(Id);}public void TakeDamage(float amount,Vector3 direction,float knockback=0,float stun=0,bool critical=false,bool impact=true,int practiceCastId=0){Health-=amount;Trace.Damage.Add(Id);Hit?.Invoke();}public void ApplyPull(Vector3 step,bool spiral=false){Pulls++;LastPull=step;}public void Provoke(){ProvokeCount++;}}
 public class EnemyStatusEffects{private readonly EnemyController enemy;public Action BeginFinale,OnPoison;public bool HasPoison=true;public int Frost,Knockups,Knockdowns;public EnemyStatusEffects(EnemyController value){enemy=value;}public void FrostMark(float seconds){Frost++;}public bool ConsumePoison(PlayerController source,int cast,out float bonus){bonus=3;return HasPoison;}public void Poison(PlayerController source,float seconds,float damage){Trace.Poison.Add(enemy.Id);OnPoison?.Invoke();}public bool BeginMeteorImpact(PlayerController p,int cast)=>false;public void Burn(PlayerController p,float seconds,float damage){}public bool TryShatter(PlayerController p,int cast)=>false;public object BeginBurnFinale(PlayerController p,int cast){BeginFinale?.Invoke();return null;}public BurnFinaleSettlement CompleteBurnFinale(object plan,float damage)=>null;public class BurnFinaleSettlement{public bool Apply()=>false;}public void Knockup(float duration,float height){Knockups++;}public void Knockdown(float duration){Knockdowns++;}}
